  }

  const user = users.find(u => u.id === userId); // Strict equality
  if (!user) {
    return res.status(404).json({ error: 'User not found' });
  }

  // Check access
  if (req.user.role !== 'admin' && req.user.id !== userId) {
    return res.status(403).json({ error: 'Access denied' });
